/* WebGen Global Styles */
:root {
  --color-primary: #2563EB;
  --color-secondary: #3B82F6;
  --color-accent: #EA580C;
  --color-bg: #F8FAFC;
  --color-fg: #1E293B;
  --font-heading: 'Poppins', system-ui, -apple-system, sans-serif;
  --font-body: 'Open Sans', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font-body);
  color: #1f2937;
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  line-height: 1.2;
}

a {
  color: var(--color-primary);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  font-weight: 600;
  transition: background-color 0.2s;
}

.btn-primary:hover {
  background-color: var(--color-secondary);
  transform: scale(1.05);
  box-shadow: 0 20px 40px rgba(0,0,0,0.2);
}

/* ── Premium animation keyframes ─────────────────── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(32px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes slideInLeft {
  from { opacity: 0; transform: translateX(-40px); }
  to   { opacity: 1; transform: translateX(0); }
}

@keyframes glowPulse {
  0%, 100% { box-shadow: 0 0 20px #EA580C4d; }
  50%       { box-shadow: 0 0 40px #EA580Cb3; }
}

@keyframes gradientShift {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* ── Glassmorphism card ───────────────────────────── */
.glass-card {
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 1rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.glass-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.3);
}

/* ── Gradient text utility ───────────────────────── */
.gradient-text {
  background: linear-gradient(90deg, #2563EB, #EA580C);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ── Animated hero gradient background ──────────── */
.hero-gradient {
  background: linear-gradient(135deg, #2563EB 0%, #3B82F6 50%, #0f172a 100%);
  background-size: 200% 200%;
  animation: gradientShift 8s ease infinite;
}

/* ── Scroll-reveal (JS-free fade) ────────────────── */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}
